import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.CdvW4CUT.js";const h=JSON.parse('{"title":"Kernel 日报 2026-11-15","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/15.md","filePath":"notes/kernel-digest/2026/11/15.md"}'),l={name:"notes/kernel-digest/2026/11/15.md"};function n(c,e,s,i,m,d){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="kernel-日报-2026-11-15" tabindex="-1">Kernel 日报 2026-11-15 <a class="header-anchor" href="#kernel-日报-2026-11-15" aria-label="Permalink to &quot;Kernel 日报 2026-11-15&quot;">​</a></h1><blockquote><p>生成时间：2026-11-15T02:51:40Z｜共 52 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-15 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="a66a51f5715e-·-rfc-patch-v4-0-4-mthp-friendly-compression-in-zsmalloc-and-zram-based-on-multi-pages" tabindex="-1"><code>a66a51f5715e</code> · <a href="https://lore.kernel.org/all/20261115024455.1465726-1-zhaonanzhe@xiaomi.com/" target="_blank" rel="noreferrer">[RFC PATCH v4 0/4] mTHP-friendly compression in zsmalloc and zram based on multi-pages</a> <a class="header-anchor" href="#a66a51f5715e-·-rfc-patch-v4-0-4-mthp-friendly-compression-in-zsmalloc-and-zram-based-on-multi-pages" aria-label="Permalink to &quot;`a66a51f5715e` · [[RFC PATCH v4 0/4] mTHP-friendly compression in zsmalloc and zram based on multi-pages](https://lore.kernel.org/all/20261115024455.1465726-1-zhaonanzhe@xiaomi.com/)&quot;">​</a></h3><p><em>Nanzhe Zhao (<a href="mailto:zhaonanzhe@xiaomi.com" target="_blank" rel="noreferrer">zhaonanzhe@xiaomi.com</a>)｜lkml｜内存管理</em></p><p>该补丁系列让 zsmalloc 和 zram 支持 mTHP（multi-size THP）友好的压缩：将 large folio 划分为多页块（典型为 order-2 粒度，即 16KiB）而非传统的每页 4KiB 块。由于 mTHP 可以整体 swap out/in 而不拆分，更大粒度的压缩显著降低 CPU 占用并提升压缩率。粒度可通过 ZSMALLOC_MULTI_PAGES_ORD 配置。</p><blockquote><p><strong>学习价值</strong>：展示了 mTHP 与 zram/zsmalloc 协同优化的思路，是理解 large folio 生态在 swap 路径落地的优秀案例。</p></blockquote><h3 id="aac6d390bfa8-·-patch-v1-net-next-0-8-tcp-prevent-tcp-collapse-from-bloating-queue" tabindex="-1"><code>aac6d390bfa8</code> · <a href="https://lore.kernel.org/all/20261114040101.1043546-1-kuniyu@google.com/" target="_blank" rel="noreferrer">[PATCH v1 net-next 0/8] tcp: Prevent tcp_collapse() from bloating queue.</a> <a class="header-anchor" href="#aac6d390bfa8-·-patch-v1-net-next-0-8-tcp-prevent-tcp-collapse-from-bloating-queue" aria-label="Permalink to &quot;`aac6d390bfa8` · [[PATCH v1 net-next 0/8] tcp: Prevent tcp_collapse() from bloating queue.](https://lore.kernel.org/all/20261114040101.1043546-1-kuniyu@google.com/)&quot;">​</a></h3><p><em>Kuniyuki Iwashima (<a href="mailto:kuniyu@google.com" target="_blank" rel="noreferrer">kuniyu@google.com</a>)｜netdev｜网络</em></p><p>本系列是 commit 031c403d13e5 的后续，修复 tcp_collapse() 在 4K MSS 和 tp-&gt;scaling_ratio 场景下反而导致内存膨胀的问题。tcp_collapse() 的核心算法自 Linux-2.6.12 以来几乎未变，将可合并的 skb 重新打包到最多 SKB_MAX_ORDER() 大小的 skb 中，但 SKB_MAX_ORDER() 的 scaling ratio（222）低于典型 4K MSS 流的 tp-&gt;scaling_ratio（252），导致重打包后内存占用不降反升。</p><blockquote><p><strong>学习价值</strong>：展示了 TCP 接收队列内存管理与现代大 MSS 特性之间的历史遗留冲突，是理解 skb 合并机制和 sk_forward_alloc 记账的好案例。</p></blockquote><h3 id="bad9ce49788a-·-patch-net-0-4-net-smc-fix-the-failover-cursor-switch-and-wrap-rollover" tabindex="-1"><code>bad9ce49788a</code> · <a href="https://lore.kernel.org/all/20261113-b4-disp-1a9ab9b0-v1-0-4a7c8d85d849@proton.me/" target="_blank" rel="noreferrer">[PATCH net 0/4] net/smc: fix the failover cursor switch and wrap rollover</a> <a class="header-anchor" href="#bad9ce49788a-·-patch-net-0-4-net-smc-fix-the-failover-cursor-switch-and-wrap-rollover" aria-label="Permalink to &quot;`bad9ce49788a` · [[PATCH net 0/4] net/smc: fix the failover cursor switch and wrap rollover](https://lore.kernel.org/all/20261113-b4-disp-1a9ab9b0-v1-0-4a7c8d85d849@proton.me/)&quot;">​</a></h3><p><em>Bryam Vargas via B4 Relay (<a href="mailto:devnull+hexlabsecurity.proton.me@kernel.org" target="_blank" rel="noreferrer">devnull+hexlabsecurity.proton.me@kernel.org</a>)｜netdev｜网络</em></p><p>本系列四补丁修复 SMC-R 链路 failover 时游标切换的多个问题：锁竞态（send_lock 与 socket spinlock 不一致）、u16 wrap 回绕导致的游标排序错误，以及旧链路迟到 completion 的重复计入。系列还引用了 CDC cursor bounds 系列的评审历史。</p><blockquote><p><strong>学习价值</strong>：作为 cover letter 系统梳理了 failover 游标切换的多个并发与回绕缺陷，是学习复杂状态机修复的绝佳材料。</p></blockquote><h3 id="_26569841c7e7-·-patch-net-next-v2-0-3-rust-net-phy-soft-reset-may-run-without-phy-device-lock" tabindex="-1"><code>26569841c7e7</code> · <a href="https://lore.kernel.org/all/20261114-exp-phy-rs-maybelocked-v2-0-19a4dd658b6b@gmail.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 0/3] rust: net: phy: soft_reset may run without phy_device-&gt;lock</a> <a class="header-anchor" href="#_26569841c7e7-·-patch-net-next-v2-0-3-rust-net-phy-soft-reset-may-run-without-phy-device-lock" aria-label="Permalink to &quot;`26569841c7e7` · [[PATCH net-next v2 0/3] rust: net: phy: soft_reset may run without phy_device-&gt;lock](https://lore.kernel.org/all/20261114-exp-phy-rs-maybelocked-v2-0-19a4dd658b6b@gmail.com/)&quot;">​</a></h3><p><em>SeungJong Ha (<a href="mailto:engineer.jjhama@gmail.com" target="_blank" rel="noreferrer">engineer.jjhama@gmail.com</a>)｜rust-for-linux｜Rust in Linux</em></p><p>该补丁系列修复 Rust PHY 抽象中 <code>soft_reset</code> 的锁假设错误：原注释声称 PHYLIB 持有 <code>phy_device-&gt;lock</code>，但 <code>phy_init_hw()</code> 实际上在有锁和无锁两种情况下都会调用它。作者通过审计 Rust 抽象的 SAFETY 注释与 C 调用方的一致性，并用 Clang 的 context analysis 确认了该问题。补丁 1 删除了同样有错误锁声明且无用户的 <code>read_mmd</code>/<code>write_mmd</code>，补丁 2-3 引入 <code>MaybeLocked</code> 锁上下文类型使 <code>Device</code> 泛型化，让类型系统精确表达锁状态。</p><blockquote><p><strong>学习价值</strong>：这是学习 Rust 抽象层如何用类型系统（如 <code>MaybeLocked</code>）表达 C 代码中隐式锁约定的绝佳案例，也展示了 SAFETY 注释审计的方法论。</p></blockquote><h3 id="_1d6e3581e68e-·-patch-v2-0-2-arm64-csum-add-fused-copy-and-internet-checksum" tabindex="-1"><code>1d6e3581e68e</code> · <a href="https://lore.kernel.org/all/20261114040943.219870-1-demyansh@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 0/2] arm64: csum: Add fused copy and Internet checksum</a> <a class="header-anchor" href="#_1d6e3581e68e-·-patch-v2-0-2-arm64-csum-add-fused-copy-and-internet-checksum" aria-label="Permalink to &quot;`1d6e3581e68e` · [[PATCH v2 0/2] arm64: csum: Add fused copy and Internet checksum](https://lore.kernel.org/all/20261114040943.219870-1-demyansh@gmail.com/)&quot;">​</a></h3><p><em>Demian Shulhan (<a href="mailto:demyansh@gmail.com" target="_blank" rel="noreferrer">demyansh@gmail.com</a>)｜netdev｜网络</em></p><p>本系列为 arm64 添加单遍 csum_partial_copy_nocheck() 实现，并扩展 checksum KUnit 测试套件覆盖不同对齐、长度、guard page 和中断上下文。v2 改动包括：去掉 NEON 路径将标量实现直接并入 arch/arm64/lib/csum.c，改用四个 __uint128_t 累加器，并在 csum_fold() 后将 0xffff（-0）规范化为 0x0000（+0）以修复 x86_64 测试失败。</p><blockquote><p><strong>学习价值</strong>：体现了补丁迭代中如何根据 review 意见调整实现，同时展示了 KUnit 跨架构测试中处理平台差异的实践。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（7 条）</li><li><strong>网络</strong>（23 条）</li><li><strong>文件系统与存储</strong>（4 条）</li><li><strong>Rust in Linux</strong>（11 条）</li><li><strong>其他动态</strong>（7 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="_1033f9509c83-·-red-hat-working-to-improve-memory-tiering-for-qemu-vms-to-save-ram" tabindex="-1"><code>1033f9509c83</code> · <a href="https://www.phoronix.com/news/QEMU-VM-Memory-Tiering" target="_blank" rel="noreferrer">Red Hat Working To Improve Memory Tiering For QEMU VMs To Save RAM</a> <a class="header-anchor" href="#_1033f9509c83-·-red-hat-working-to-improve-memory-tiering-for-qemu-vms-to-save-ram" aria-label="Permalink to &quot;`1033f9509c83` · [Red Hat Working To Improve Memory Tiering For QEMU VMs To Save RAM](https://www.phoronix.com/news/QEMU-VM-Memory-Tiering)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Red Hat 工程师正在探索多种方案增强 QEMU 虚拟机的 memory tiering，在内存价格高企的背景下，希望更多场景利用 NVMe SSD 承载冷数据以节省 RAM。相关讨论涉及虚拟机内存分层与冷热页分离机制。</p><blockquote><p><strong>学习价值</strong>：有助于理解 Linux memory tiering（如 DAMON、KSM、冷页降级）在虚拟化场景的实际工程动机与权衡。</p></blockquote><h3 id="_5854c51b31f7-·-rfc-patch-v4-2-4-zram-support-compression-at-the-granularity-of-multi-pages" tabindex="-1"><code>5854c51b31f7</code> · <a href="https://lore.kernel.org/all/20261115024455.1465726-3-zhaonanzhe@xiaomi.com/" target="_blank" rel="noreferrer">[RFC PATCH v4 2/4] zram: support compression at the granularity of multi-pages</a> <a class="header-anchor" href="#_5854c51b31f7-·-rfc-patch-v4-2-4-zram-support-compression-at-the-granularity-of-multi-pages" aria-label="Permalink to &quot;`5854c51b31f7` · [[RFC PATCH v4 2/4] zram: support compression at the granularity of multi-pages](https://lore.kernel.org/all/20261115024455.1465726-3-zhaonanzhe@xiaomi.com/)&quot;">​</a></h3><p><em>Nanzhe Zhao (<a href="mailto:zhaonanzhe@xiaomi.com" target="_blank" rel="noreferrer">zhaonanzhe@xiaomi.com</a>)｜lkml</em></p><p>该补丁为 zram 引入多页粒度的压缩支持：大 folio 不再按单页逐一压缩，而是按 ZSMALLOC_MULTI_PAGES_ORDER（默认 2，即 16KiB）的粒度切分压缩。例如 128KiB 的 folio 会被分成 8 个 16KiB 块压缩，可显著提升压缩率并降低 CPU 消耗。</p><blockquote><p><strong>学习价值</strong>：是学习 zram/zsmalloc 压缩路径与 large folio 交互的优秀实例，展示了压缩粒度与压缩率、CPU 开销之间的权衡。</p></blockquote><h3 id="_772b95abf5bb-·-rfc-patch-v4-4-4-mm-swap-allow-direct-reclaim-for-synchronous-multi-page-swapin" tabindex="-1"><code>772b95abf5bb</code> · <a href="https://lore.kernel.org/all/20261115024455.1465726-5-zhaonanzhe@xiaomi.com/" target="_blank" rel="noreferrer">[RFC PATCH v4 4/4] mm: swap: allow direct reclaim for synchronous multi-page swapin</a> <a class="header-anchor" href="#_772b95abf5bb-·-rfc-patch-v4-4-4-mm-swap-allow-direct-reclaim-for-synchronous-multi-page-swapin" aria-label="Permalink to &quot;`772b95abf5bb` · [[RFC PATCH v4 4/4] mm: swap: allow direct reclaim for synchronous multi-page swapin](https://lore.kernel.org/all/20261115024455.1465726-5-zhaonanzhe@xiaomi.com/)&quot;">​</a></h3><p><em>Nanzhe Zhao (<a href="mailto:zhaonanzhe@xiaomi.com" target="_blank" rel="noreferrer">zhaonanzhe@xiaomi.com</a>)｜lkml</em></p><p>该补丁允许同步多页 swapin（如 zram 场景）在 order-2 分配失败时进行 direct reclaim。因为 swapin 分配继承了 VMA 的 THP gfp mask，未设置 MADV_HUGEPAGE 的 VMA 会去掉 __GFP_DIRECT_RECLAIM，导致内存压力下回退到 order-0，却仍需解压整个 16KiB 块，造成浪费。</p><blockquote><p><strong>学习价值</strong>：深入展示了 gfp mask、THP 策略与 swapin 路径的耦合关系，对理解内存压力下的分配回退机制很有价值。</p></blockquote><h3 id="a66a51f5715e-·-rfc-patch-v4-0-4-mthp-friendly-compression-in-zsmalloc-and-zram-based-on-multi-pages-1" tabindex="-1"><code>a66a51f5715e</code> · <a href="https://lore.kernel.org/all/20261115024455.1465726-1-zhaonanzhe@xiaomi.com/" target="_blank" rel="noreferrer">[RFC PATCH v4 0/4] mTHP-friendly compression in zsmalloc and zram based on multi-pages</a> <a class="header-anchor" href="#a66a51f5715e-·-rfc-patch-v4-0-4-mthp-friendly-compression-in-zsmalloc-and-zram-based-on-multi-pages-1" aria-label="Permalink to &quot;`a66a51f5715e` · [[RFC PATCH v4 0/4] mTHP-friendly compression in zsmalloc and zram based on multi-pages](https://lore.kernel.org/all/20261115024455.1465726-1-zhaonanzhe@xiaomi.com/)&quot;">​</a></h3><p><em>Nanzhe Zhao (<a href="mailto:zhaonanzhe@xiaomi.com" target="_blank" rel="noreferrer">zhaonanzhe@xiaomi.com</a>)｜lkml</em></p><p>该补丁系列让 zsmalloc 和 zram 支持 mTHP（multi-size THP）友好的压缩：将 large folio 划分为多页块（典型为 order-2 粒度，即 16KiB）而非传统的每页 4KiB 块。由于 mTHP 可以整体 swap out/in 而不拆分，更大粒度的压缩显著降低 CPU 占用并提升压缩率。粒度可通过 ZSMALLOC_MULTI_PAGES_ORD 配置。</p><blockquote><p><strong>学习价值</strong>：展示了 mTHP 与 zram/zsmalloc 协同优化的思路，是理解 large folio 生态在 swap 路径落地的优秀案例。</p></blockquote><h3 id="_9c926d30ddec-·-rfc-patch-v4-3-4-zram-backend-zstd-use-multi-page-size-for-zstd-parameter-setup" tabindex="-1"><code>9c926d30ddec</code> · <a href="https://lore.kernel.org/all/20261115024455.1465726-4-zhaonanzhe@xiaomi.com/" target="_blank" rel="noreferrer">[RFC PATCH v4 3/4] zram: backend_zstd: use multi-page size for zstd parameter setup</a> <a class="header-anchor" href="#_9c926d30ddec-·-rfc-patch-v4-3-4-zram-backend-zstd-use-multi-page-size-for-zstd-parameter-setup" aria-label="Permalink to &quot;`9c926d30ddec` · [[RFC PATCH v4 3/4] zram: backend_zstd: use multi-page size for zstd parameter setup](https://lore.kernel.org/all/20261115024455.1465726-4-zhaonanzhe@xiaomi.com/)&quot;">​</a></h3><p><em>Nanzhe Zhao (<a href="mailto:zhaonanzhe@xiaomi.com" target="_blank" rel="noreferrer">zhaonanzhe@xiaomi.com</a>)｜lkml</em></p><p>zram 的 zstd 后端在 zstd_setup_params() 中原本向 zstd_get_params()/zstd_get_cparams() 传入 PAGE_SIZE 作为源大小提示，导致压缩 16KiB 多页块时 zstd 的匹配窗口被限制在单页内，无法发现跨页冗余。补丁改为传入 ZCOMP_MULTI_PAGES_SIZE，使 zstd 按多页块大小配置参数。</p><blockquote><p><strong>学习价值</strong>：提醒学习者压缩算法参数（如窗口大小）与实际压缩单元粒度必须匹配，否则会静默损失压缩率。</p></blockquote><h3 id="_1a3b2b8a139d-·-linux-next-master-build-regression-84abb955b1015477aa11a96e2f3ac1b938b77f48" tabindex="-1"><code>1a3b2b8a139d</code> · <a href="https://lore.kernel.org/all/20261115084624.OkSIe5ZA-lkp@intel.com/" target="_blank" rel="noreferrer">[linux-next:master] BUILD REGRESSION 84abb955b1015477aa11a96e2f3ac1b938b77f48</a> <a class="header-anchor" href="#_1a3b2b8a139d-·-linux-next-master-build-regression-84abb955b1015477aa11a96e2f3ac1b938b77f48" aria-label="Permalink to &quot;`1a3b2b8a139d` · [[linux-next:master] BUILD REGRESSION 84abb955b1015477aa11a96e2f3ac1b938b77f48](https://lore.kernel.org/all/20261115084624.OkSIe5ZA-lkp@intel.com/)&quot;">​</a></h3><p><em>kernel test robot (<a href="mailto:lkp@intel.com" target="_blank" rel="noreferrer">lkp@intel.com</a>)｜linux-mm</em></p><p>kernel test robot 报告 linux-next master 分支出现构建回归：leds-asus-aura-scsi.c 引用了未定义的 scsi_register_device_handler()，导致 arc 架构链接失败。报告同时列出若干未验证的疑似误报。</p><blockquote><p><strong>学习价值</strong>：展示了 0-day/lkp 自动化构建测试如何捕获跨子系统链接依赖问题，可了解内核 CI 的运作方式。</p></blockquote><h3 id="_6d34f287a615-·-akpm-mm-mm-new-build-success-6ec534d64f85e949a5d58070678dcd7711875a7c" tabindex="-1"><code>6d34f287a615</code> · <a href="https://lore.kernel.org/all/20261115052113.pCDYACX7-lkp@intel.com/" target="_blank" rel="noreferrer">[akpm-mm:mm-new] BUILD SUCCESS 6ec534d64f85e949a5d58070678dcd7711875a7c</a> <a class="header-anchor" href="#_6d34f287a615-·-akpm-mm-mm-new-build-success-6ec534d64f85e949a5d58070678dcd7711875a7c" aria-label="Permalink to &quot;`6d34f287a615` · [[akpm-mm:mm-new] BUILD SUCCESS 6ec534d64f85e949a5d58070678dcd7711875a7c](https://lore.kernel.org/all/20261115052113.pCDYACX7-lkp@intel.com/)&quot;">​</a></h3><p><em>kernel test robot (<a href="mailto:lkp@intel.com" target="_blank" rel="noreferrer">lkp@intel.com</a>)｜linux-mm</em></p><p>kernel test robot 报告 akpm 的 mm-new 分支（HEAD 6ec534d64f85）在 344 个配置下构建成功，耗时 793 分钟。该 HEAD 包含补丁 &quot;mm/madvise: zap markers from guard regions&quot;，涉及 alpha 等多种架构和编译器组合的测试。</p><blockquote><p><strong>学习价值</strong>：展示了 0-day/LKP 自动化构建测试流程，是了解 mm 子系统补丁如何被大规模验证的实例。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="a161fba79f22-·-patch-net-next-v3-6-6-selftests-net-add-leased-devmem-rx-and-tx-netdev-unregister-tests" tabindex="-1"><code>a161fba79f22</code> · <a href="https://lore.kernel.org/all/20261115022607.348112-7-almasrymina@google.com/" target="_blank" rel="noreferrer">[PATCH net-next v3 6/6] selftests: net: add leased devmem RX and TX netdev unregister tests</a> <a class="header-anchor" href="#a161fba79f22-·-patch-net-next-v3-6-6-selftests-net-add-leased-devmem-rx-and-tx-netdev-unregister-tests" aria-label="Permalink to &quot;`a161fba79f22` · [[PATCH net-next v3 6/6] selftests: net: add leased devmem RX and TX netdev unregister tests](https://lore.kernel.org/all/20261115022607.348112-7-almasrymina@google.com/)&quot;">​</a></h3><p><em>Mina Almasry (<a href="mailto:almasrymina@google.com" target="_blank" rel="noreferrer">almasrymina@google.com</a>)｜lkml</em></p><p>扩展 nl_netdev.py 自测脚本，覆盖 devmem RX/TX 绑定活跃时的 netdev 注销场景：netkit 虚拟设备从 netdevsim 租借 RX 队列。测试验证了先删除虚拟设备（解除租借）和直接注销底层 netdevsim（级联注销租借方）两种路径下的干净卸载。</p><blockquote><p><strong>学习价值</strong>：演示了如何为复杂的设备生命周期（devmem 绑定 + 队列租借）编写 netlink 自测脚本，是学习 netdevsim/netkit 测试基础设施的好材料。</p></blockquote><h3 id="_09bf4228dbbb-·-patch-net-next-v3-0-6-net-devmem-support-leased-rx-and-tx-queues-on-netdev-unregister" tabindex="-1"><code>09bf4228dbbb</code> · <a href="https://lore.kernel.org/all/20261115022607.348112-1-almasrymina@google.com/" target="_blank" rel="noreferrer">[PATCH net-next v3 0/6] net: devmem: support leased RX and TX queues on netdev unregister</a> <a class="header-anchor" href="#_09bf4228dbbb-·-patch-net-next-v3-0-6-net-devmem-support-leased-rx-and-tx-queues-on-netdev-unregister" aria-label="Permalink to &quot;`09bf4228dbbb` · [[PATCH net-next v3 0/6] net: devmem: support leased RX and TX queues on netdev unregister](https://lore.kernel.org/all/20261115022607.348112-1-almasrymina@google.com/)&quot;">​</a></h3><p><em>Mina Almasry (<a href="mailto:almasrymina@google.com" target="_blank" rel="noreferrer">almasrymina@google.com</a>)｜lkml</em></p><p>该系列支持在虚拟设备（如 netkit）或物理底层 net_device 注销时正确处理租借的 RX/TX devmem 绑定。核心改动包括：net_devmem_lock_dev() 接受 struct net_device ** 以便锁定 map_dev 或 bind_dev；将 binding-&gt;dev/vdev 重命名为语义更清晰的 map_dev/bind_dev；引入 netif_lease_valid() 并在 netif_mp_open_rxq() 等路径中防护正在注销的物理设备。</p><blockquote><p><strong>学习价值</strong>：展示了 devmem（dmabuf 绑定）与队列租借机制下的设备引用与注销生命周期设计，对理解 netdev 内存提供者架构很有价值。</p></blockquote><h3 id="_2a011e5a5b7e-·-patch-hwmon-pmbus-xdp710-use-dev-err-probe" tabindex="-1"><code>2a011e5a5b7e</code> · <a href="https://lore.kernel.org/all/20261115022053.32321-1-niloymeharchandani@gmail.com/" target="_blank" rel="noreferrer">[PATCH] hwmon: (pmbus/xdp710) Use dev_err_probe()</a> <a class="header-anchor" href="#_2a011e5a5b7e-·-patch-hwmon-pmbus-xdp710-use-dev-err-probe" aria-label="Permalink to &quot;`2a011e5a5b7e` · [[PATCH] hwmon: (pmbus/xdp710) Use dev_err_probe()](https://lore.kernel.org/all/20261115022053.32321-1-niloymeharchandani@gmail.com/)&quot;">​</a></h3><p><em>Niloy Meharchandani (<a href="mailto:niloymeharchandani@gmail.com" target="_blank" rel="noreferrer">niloymeharchandani@gmail.com</a>)｜lkml</em></p><p>将 hwmon pmbus/xdp710 驱动的 xdp710_probe() 中的 dev_err() + return 改为 dev_err_probe()，简化错误路径并以符号形式打印错误码。无功能变化，仅编译测试。</p><blockquote><p><strong>学习价值</strong>：一个入门级清理补丁，适合作为新人的 first patch 参考范例，理解 dev_err_probe() 的使用规范。</p></blockquote><h3 id="_0ef1d7f05728-·-patch-net-2-2-net-usb-smsc95xx-propagate-mdio-write-errors" tabindex="-1"><code>0ef1d7f05728</code> · <a href="https://lore.kernel.org/all/20261114050954.275495-3-artem122novak@gmail.com/" target="_blank" rel="noreferrer">[PATCH net 2/2] net: usb: smsc95xx: propagate MDIO write errors</a> <a class="header-anchor" href="#_0ef1d7f05728-·-patch-net-2-2-net-usb-smsc95xx-propagate-mdio-write-errors" aria-label="Permalink to &quot;`0ef1d7f05728` · [[PATCH net 2/2] net: usb: smsc95xx: propagate MDIO write errors](https://lore.kernel.org/all/20261114050954.275495-3-artem122novak@gmail.com/)&quot;">​</a></h3><p><em>Artem Novak (<a href="mailto:artem122novak@gmail.com" target="_blank" rel="noreferrer">artem122novak@gmail.com</a>)｜netdev</em></p><p>该补丁修复 smsc95xx USB 网卡驱动中 MDIO write helper 丢弃寄存器访问错误的问题，使 MDIO bus callback 在写入失败时正确返回错误。设备断开时的 -ENODEV 仍按成功处理，与 MDIO read 路径保持一致。</p><blockquote><p><strong>学习价值</strong>：展示了驱动中错误传播（error propagation）的典型修复模式，对学习 PHY/MDIO 子系统的错误处理约定很有帮助。</p></blockquote><h3 id="_6d8a5790c48d-·-patch-net-1-2-net-usb-smsc95xx-propagate-mdio-reset-errors" tabindex="-1"><code>6d8a5790c48d</code> · <a href="https://lore.kernel.org/all/20261114050954.275495-2-artem122novak@gmail.com/" target="_blank" rel="noreferrer">[PATCH net 1/2] net: usb: smsc95xx: propagate MDIO reset errors</a> <a class="header-anchor" href="#_6d8a5790c48d-·-patch-net-1-2-net-usb-smsc95xx-propagate-mdio-reset-errors" aria-label="Permalink to &quot;`6d8a5790c48d` · [[PATCH net 1/2] net: usb: smsc95xx: propagate MDIO reset errors](https://lore.kernel.org/all/20261114050954.275495-2-artem122novak@gmail.com/)&quot;">​</a></h3><p><em>Artem Novak (<a href="mailto:artem122novak@gmail.com" target="_blank" rel="noreferrer">artem122novak@gmail.com</a>)｜netdev</em></p><p>该补丁修复 smsc95xx 驱动 MDIO bus reset callback 的问题：即使读写 PHY reset control 寄存器失败也返回成功。修改后寄存器访问错误会被返回，调用者可以检测到 PHY 复位失败。</p><blockquote><p><strong>学习价值</strong>：一个简洁的单行错误处理修复，适合学习 MDIO 回调接口的语义和责任划分。</p></blockquote><h3 id="_839ff0ac4d8d-·-patch-net-0-2-net-usb-smsc95xx-propagate-mdio-errors" tabindex="-1"><code>839ff0ac4d8d</code> · <a href="https://lore.kernel.org/all/20261114050954.275495-1-artem122novak@gmail.com/" target="_blank" rel="noreferrer">[PATCH net 0/2] net: usb: smsc95xx: propagate MDIO errors</a> <a class="header-anchor" href="#_839ff0ac4d8d-·-patch-net-0-2-net-usb-smsc95xx-propagate-mdio-errors" aria-label="Permalink to &quot;`839ff0ac4d8d` · [[PATCH net 0/2] net: usb: smsc95xx: propagate MDIO errors](https://lore.kernel.org/all/20261114050954.275495-1-artem122novak@gmail.com/)&quot;">​</a></h3><p><em>Artem Novak (<a href="mailto:artem122novak@gmail.com" target="_blank" rel="noreferrer">artem122novak@gmail.com</a>)｜netdev</em></p><p>本系列共两补丁，修复 SMSC95xx USB 网卡驱动 MDIO 操作的错误处理：一是让外部 PHY reset callback 返回寄存器访问错误，二是让 MDIO write 错误通过 bus callback 正确传播（保留断开时对 -ENODEV 的处理）。改进了向 MDIO/PHYLIB 层的错误上报。</p><blockquote><p><strong>学习价值</strong>：作为 cover letter 展示了小型修复系列的完整结构，是学习补丁系列组织方式的好例子。</p></blockquote><h3 id="_05b6f753f0da-·-patch-net-3-4-net-smc-fix-the-failover-catch-up-across-the-cursor-wrap-rollover" tabindex="-1"><code>05b6f753f0da</code> · <a href="https://lore.kernel.org/all/20261113-b4-disp-1a9ab9b0-v1-3-4a7c8d85d849@proton.me/" target="_blank" rel="noreferrer">[PATCH net 3/4] net/smc: fix the failover catch-up across the cursor wrap rollover</a> <a class="header-anchor" href="#_05b6f753f0da-·-patch-net-3-4-net-smc-fix-the-failover-catch-up-across-the-cursor-wrap-rollover" aria-label="Permalink to &quot;`05b6f753f0da` · [[PATCH net 3/4] net/smc: fix the failover catch-up across the cursor wrap rollover](https://lore.kernel.org/all/20261113-b4-disp-1a9ab9b0-v1-3-4a7c8d85d849@proton.me/)&quot;">​</a></h3><p><em>Bryam Vargas via B4 Relay (<a href="mailto:devnull+hexlabsecurity.proton.me@kernel.org" target="_blank" rel="noreferrer">devnull+hexlabsecurity.proton.me@kernel.org</a>)｜netdev</em></p><p>修复 SMC（Shared Memory Communications）协议中 smc_switch_cursor() 使用 smc_curs_comp() 比较游标时在 u16 wrap 从 65535 回绕到 0 时排序错误的问题。错误的 catch-up 可能给从未发送的字节计入 sndbuf_space，导致下次 send() 越过发送缓冲区末尾复制。</p><blockquote><p><strong>学习价值</strong>：展示了无符号 16 位回绕游标比较这一经典内核陷阱，对理解环形缓冲区游标序关系极有价值。</p></blockquote><h3 id="_0634b2524ae0-·-patch-net-2-4-net-smc-do-not-credit-stale-cdc-completions-after-a-link-switch" tabindex="-1"><code>0634b2524ae0</code> · <a href="https://lore.kernel.org/all/20261113-b4-disp-1a9ab9b0-v1-2-4a7c8d85d849@proton.me/" target="_blank" rel="noreferrer">[PATCH net 2/4] net/smc: do not credit stale CDC completions after a link switch</a> <a class="header-anchor" href="#_0634b2524ae0-·-patch-net-2-4-net-smc-do-not-credit-stale-cdc-completions-after-a-link-switch" aria-label="Permalink to &quot;`0634b2524ae0` · [[PATCH net 2/4] net/smc: do not credit stale CDC completions after a link switch](https://lore.kernel.org/all/20261113-b4-disp-1a9ab9b0-v1-2-4a7c8d85d849@proton.me/)&quot;">​</a></h3><p><em>Bryam Vargas via B4 Relay (<a href="mailto:devnull+hexlabsecurity.proton.me@kernel.org" target="_blank" rel="noreferrer">devnull+hexlabsecurity.proton.me@kernel.org</a>)｜netdev</em></p><p>修复 SMC 链路切换后旧链路上迟到的 CDC completion 仍被计入的问题：这可能导致应用在数据重发前覆盖发送缓冲区，或 sndbuf_space 超过缓冲区大小。方案是为每个 CDC pend 标记 switch generation，由 smc_switch_cursor() 进行区分。</p><blockquote><p><strong>学习价值</strong>：展示了链路 failover 场景下异步完成事件的竞态处理，是学习并发状态一致性设计的优秀案例。</p></blockquote><h3 id="b4b8405983ac-·-patch-net-4-4-net-smc-order-the-urgent-mark-across-the-cursor-wrap-rollover" tabindex="-1"><code>b4b8405983ac</code> · <a href="https://lore.kernel.org/all/20261113-b4-disp-1a9ab9b0-v1-4-4a7c8d85d849@proton.me/" target="_blank" rel="noreferrer">[PATCH net 4/4] net/smc: order the urgent mark across the cursor wrap rollover</a> <a class="header-anchor" href="#b4b8405983ac-·-patch-net-4-4-net-smc-order-the-urgent-mark-across-the-cursor-wrap-rollover" aria-label="Permalink to &quot;`b4b8405983ac` · [[PATCH net 4/4] net/smc: order the urgent mark across the cursor wrap rollover](https://lore.kernel.org/all/20261113-b4-disp-1a9ab9b0-v1-4-4a7c8d85d849@proton.me/)&quot;">​</a></h3><p><em>Bryam Vargas via B4 Relay (<a href="mailto:devnull+hexlabsecurity.proton.me@kernel.org" target="_blank" rel="noreferrer">devnull+hexlabsecurity.proton.me@kernel.org</a>)｜netdev</em></p><p>修复 SMC 接收路径中 smc_rx_update_consumer() 在 RMB wrap 从 65535 回绕到 0 时对 urgent 游标排序错误的问题。在未设置 SO_OOBINLINE 时，urgent 标记可能被误判为已读，导致 recv(MSG_OOB) 返回 -EINVAL 且连接死锁。</p><blockquote><p><strong>学习价值</strong>：结合带外数据（urgent/OOB）处理讲解游标回绕 bug，对理解 TCP 类语义在 SMC 中的实现很有参考价值。</p></blockquote><h3 id="ab8e767b1ada-·-patch-net-1-4-net-smc-take-the-socket-spinlock-across-the-failover-cursor-switch" tabindex="-1"><code>ab8e767b1ada</code> · <a href="https://lore.kernel.org/all/20261113-b4-disp-1a9ab9b0-v1-1-4a7c8d85d849@proton.me/" target="_blank" rel="noreferrer">[PATCH net 1/4] net/smc: take the socket spinlock across the failover cursor switch</a> <a class="header-anchor" href="#ab8e767b1ada-·-patch-net-1-4-net-smc-take-the-socket-spinlock-across-the-failover-cursor-switch" aria-label="Permalink to &quot;`ab8e767b1ada` · [[PATCH net 1/4] net/smc: take the socket spinlock across the failover cursor switch](https://lore.kernel.org/all/20261113-b4-disp-1a9ab9b0-v1-1-4a7c8d85d849@proton.me/)&quot;">​</a></h3><p><em>Bryam Vargas via B4 Relay (<a href="mailto:devnull+hexlabsecurity.proton.me@kernel.org" target="_blank" rel="noreferrer">devnull+hexlabsecurity.proton.me@kernel.org</a>)｜netdev</em></p><p>修复 SMC 链路 failover 时 smc_switch_cursor() 仅持有 send_lock，而 CDC 发送完成和接收路径在 bh_lock_sock() 下更新相同游标的竞态问题。切换期间的 CDC completion 可能导致字节被重复计入或游标失步，使重发写入错误的 RMB 偏移。修复是在游标切换全程持有 socket 自旋锁。</p><blockquote><p><strong>学习价值</strong>：典型的锁覆盖范围不足导致的竞态案例，对学习内核锁的粒度设计与软中断上下文同步很有帮助。</p></blockquote><h3 id="bad9ce49788a-·-patch-net-0-4-net-smc-fix-the-failover-cursor-switch-and-wrap-rollover-1" tabindex="-1"><code>bad9ce49788a</code> · <a href="https://lore.kernel.org/all/20261113-b4-disp-1a9ab9b0-v1-0-4a7c8d85d849@proton.me/" target="_blank" rel="noreferrer">[PATCH net 0/4] net/smc: fix the failover cursor switch and wrap rollover</a> <a class="header-anchor" href="#bad9ce49788a-·-patch-net-0-4-net-smc-fix-the-failover-cursor-switch-and-wrap-rollover-1" aria-label="Permalink to &quot;`bad9ce49788a` · [[PATCH net 0/4] net/smc: fix the failover cursor switch and wrap rollover](https://lore.kernel.org/all/20261113-b4-disp-1a9ab9b0-v1-0-4a7c8d85d849@proton.me/)&quot;">​</a></h3><p><em>Bryam Vargas via B4 Relay (<a href="mailto:devnull+hexlabsecurity.proton.me@kernel.org" target="_blank" rel="noreferrer">devnull+hexlabsecurity.proton.me@kernel.org</a>)｜netdev</em></p><p>本系列四补丁修复 SMC-R 链路 failover 时游标切换的多个问题：锁竞态（send_lock 与 socket spinlock 不一致）、u16 wrap 回绕导致的游标排序错误，以及旧链路迟到 completion 的重复计入。系列还引用了 CDC cursor bounds 系列的评审历史。</p><blockquote><p><strong>学习价值</strong>：作为 cover letter 系统梳理了 failover 游标切换的多个并发与回绕缺陷，是学习复杂状态机修复的绝佳材料。</p></blockquote><h3 id="b361b86c10f0-·-patch-v2-2-2-lib-tests-checksum-add-kunit-tests-for-csum-partial-copy-nocheck" tabindex="-1"><code>b361b86c10f0</code> · <a href="https://lore.kernel.org/all/20261114040943.219870-3-demyansh@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 2/2] lib/tests: checksum: Add KUnit tests for csum_partial_copy_nocheck()</a> <a class="header-anchor" href="#b361b86c10f0-·-patch-v2-2-2-lib-tests-checksum-add-kunit-tests-for-csum-partial-copy-nocheck" aria-label="Permalink to &quot;`b361b86c10f0` · [[PATCH v2 2/2] lib/tests: checksum: Add KUnit tests for csum_partial_copy_nocheck()](https://lore.kernel.org/all/20261114040943.219870-3-demyansh@gmail.com/)&quot;">​</a></h3><p><em>Demian Shulhan (<a href="mailto:demyansh@gmail.com" target="_blank" rel="noreferrer">demyansh@gmail.com</a>)｜netdev</em></p><p>为 csum_partial_copy_nocheck() 扩展 KUnit 测试：覆盖多种对齐、尾部长度、位模式、vmalloc() guard page 与并发执行场景，并将折叠校验和与 C 参考实现及 csum_partial() 对比，规范化 0xffff 为 0x0000 以兼容 x86_64 等架构。另提供默认关闭的吞吐量基准测试选项。</p><blockquote><p><strong>学习价值</strong>：展示了如何为架构相关的基础库函数编写跨架构 KUnit 测试，是学习内核测试基础设施的实用范例。</p></blockquote><h3 id="_5839dce7b5b2-·-patch-v2-1-2-arm64-csum-add-fused-copy-and-internet-checksum" tabindex="-1"><code>5839dce7b5b2</code> · <a href="https://lore.kernel.org/all/20261114040943.219870-2-demyansh@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 1/2] arm64: csum: Add fused copy and Internet checksum</a> <a class="header-anchor" href="#_5839dce7b5b2-·-patch-v2-1-2-arm64-csum-add-fused-copy-and-internet-checksum" aria-label="Permalink to &quot;`5839dce7b5b2` · [[PATCH v2 1/2] arm64: csum: Add fused copy and Internet checksum](https://lore.kernel.org/all/20261114040943.219870-2-demyansh@gmail.com/)&quot;">​</a></h3><p><em>Demian Shulhan (<a href="mailto:demyansh@gmail.com" target="_blank" rel="noreferrer">demyansh@gmail.com</a>)｜netdev</em></p><p>arm64 目前回退到 lib/checksum.c 中的通用 csum_partial_copy_nocheck()，先 memcpy() 再做第二遍 csum_partial()，在软件 GSO 路径（如 TCP over WireGuard）和 UDP/ICMP 回复中造成双重遍历。本补丁在 arch/arm64/lib/csum.c 中实现单遍 fused copy-and-checksum，使用四个独立的 __uint128_t 累加器按 32 字节步长处理，并配对发射 ldp/stp 与 adds/cinc 指令。</p><blockquote><p><strong>学习价值</strong>：展示了如何针对特定架构优化网络校验和热路径，是学习 arm64 汇编级优化与 checksum 子系统的优秀案例。</p></blockquote><h3 id="_1d6e3581e68e-·-patch-v2-0-2-arm64-csum-add-fused-copy-and-internet-checksum-1" tabindex="-1"><code>1d6e3581e68e</code> · <a href="https://lore.kernel.org/all/20261114040943.219870-1-demyansh@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 0/2] arm64: csum: Add fused copy and Internet checksum</a> <a class="header-anchor" href="#_1d6e3581e68e-·-patch-v2-0-2-arm64-csum-add-fused-copy-and-internet-checksum-1" aria-label="Permalink to &quot;`1d6e3581e68e` · [[PATCH v2 0/2] arm64: csum: Add fused copy and Internet checksum](https://lore.kernel.org/all/20261114040943.219870-1-demyansh@gmail.com/)&quot;">​</a></h3><p><em>Demian Shulhan (<a href="mailto:demyansh@gmail.com" target="_blank" rel="noreferrer">demyansh@gmail.com</a>)｜netdev</em></p><p>本系列为 arm64 添加单遍 csum_partial_copy_nocheck() 实现，并扩展 checksum KUnit 测试套件覆盖不同对齐、长度、guard page 和中断上下文。v2 改动包括：去掉 NEON 路径将标量实现直接并入 arch/arm64/lib/csum.c，改用四个 __uint128_t 累加器，并在 csum_fold() 后将 0xffff（-0）规范化为 0x0000（+0）以修复 x86_64 测试失败。</p><blockquote><p><strong>学习价值</strong>：体现了补丁迭代中如何根据 review 意见调整实现，同时展示了 KUnit 跨架构测试中处理平台差异的实践。</p></blockquote><h3 id="_7fd1b4d77a07-·-patch-v1-net-next-8-8-selftest-packetdrill-add-test-for-tcp-collapse" tabindex="-1"><code>7fd1b4d77a07</code> · <a href="https://lore.kernel.org/all/20261114040101.1043546-9-kuniyu@google.com/" target="_blank" rel="noreferrer">[PATCH v1 net-next 8/8] selftest: packetdrill: Add test for tcp_collapse().</a> <a class="header-anchor" href="#_7fd1b4d77a07-·-patch-v1-net-next-8-8-selftest-packetdrill-add-test-for-tcp-collapse" aria-label="Permalink to &quot;`7fd1b4d77a07` · [[PATCH v1 net-next 8/8] selftest: packetdrill: Add test for tcp_collapse().](https://lore.kernel.org/all/20261114040101.1043546-9-kuniyu@google.com/)&quot;">​</a></h3><p><em>Kuniyuki Iwashima (<a href="mailto:kuniyu@google.com" target="_blank" rel="noreferrer">kuniyu@google.com</a>)｜netdev</em></p><p>该补丁为 tcp_collapse() 的新行为添加 packetdrill 自测：通过设置大小不同的 SO_RCVBUF、发送高/低密度 skb 组合并触发 tcp_collapse()，再用 nstat 检查 TcpExtTCPRcvCollapsed 计数，验证高密度 skb 及被其夹住的低密度 skb 不再被错误合并。</p><blockquote><p><strong>学习价值</strong>：示范了如何用 packetdrill 编写协议行为回归测试，是学习 TCP 接收队列内存整理逻辑的实用入口。</p></blockquote><h3 id="_87aa93819090-·-patch-v1-net-next-7-8-tcp-batch-memory-accounting-in-tcp-collapse" tabindex="-1"><code>87aa93819090</code> · <a href="https://lore.kernel.org/all/20261114040101.1043546-8-kuniyu@google.com/" target="_blank" rel="noreferrer">[PATCH v1 net-next 7/8] tcp: Batch memory accounting in tcp_collapse().</a> <a class="header-anchor" href="#_87aa93819090-·-patch-v1-net-next-7-8-tcp-batch-memory-accounting-in-tcp-collapse" aria-label="Permalink to &quot;`87aa93819090` · [[PATCH v1 net-next 7/8] tcp: Batch memory accounting in tcp_collapse().](https://lore.kernel.org/all/20261114040101.1043546-8-kuniyu@google.com/)&quot;">​</a></h3><p><em>Kuniyuki Iwashima (<a href="mailto:kuniyu@google.com" target="_blank" rel="noreferrer">kuniyu@google.com</a>)｜netdev</em></p><p>tcp_collapse_one() 调用 sock_rfree() 后，sk_mem_uncharge() 会在 sk-&gt;sk_forward_alloc 达到 4K 时立即向下取整回收内存（源自 commit 4890b686f408），导致新分配 skb 的 skb_set_owner_r() 使 sk_forward_alloc 下溢并依赖 sk_forced_mem_schedule()。补丁改为在 tcp_collapse() 过程中缓存增量并在结束时批量记账，从而消除对 sk_forced_mem_schedule() 的需求。</p><blockquote><p><strong>学习价值</strong>：深入剖析了 socket 内存记账（sk_forward_alloc、sk_mem_uncharge）机制，对理解 TCP 内存管理细节很有价值。</p></blockquote><h3 id="b2a996c6adfe-·-patch-v1-net-next-6-8-tcp-allocate-all-new-skb-before-collapsing" tabindex="-1"><code>b2a996c6adfe</code> · <a href="https://lore.kernel.org/all/20261114040101.1043546-7-kuniyu@google.com/" target="_blank" rel="noreferrer">[PATCH v1 net-next 6/8] tcp: Allocate all new skb before collapsing.</a> <a class="header-anchor" href="#b2a996c6adfe-·-patch-v1-net-next-6-8-tcp-allocate-all-new-skb-before-collapsing" aria-label="Permalink to &quot;`b2a996c6adfe` · [[PATCH v1 net-next 6/8] tcp: Allocate all new skb before collapsing.](https://lore.kernel.org/all/20261114040101.1043546-7-kuniyu@google.com/)&quot;">​</a></h3><p><em>Kuniyuki Iwashima (<a href="mailto:kuniyu@google.com" target="_blank" rel="noreferrer">kuniyu@google.com</a>)｜netdev</em></p><p>tcp_collapse() 在最后阶段逐个分配新 skb 并重打包候选 skb，但若拆分大 bloated skb 时 alloc_skb() 失败，部分拷贝的 skb 不会被移除，新 skb 作为重复项留在队列中反而消耗更多内存。补丁改为在合并前预分配所有 skb，只有全部成功才执行合并，避免复杂的回滚逻辑。</p><blockquote><p><strong>学习价值</strong>：展示了内核中“先预分配再操作”的错误处理模式，是学习 skb 生命周期与失败路径设计的良好范例。</p></blockquote><h3 id="_895c85f2151c-·-patch-v1-net-next-5-8-tcp-skip-collapsing-if-collapsed-skb-is-less-dense" tabindex="-1"><code>895c85f2151c</code> · <a href="https://lore.kernel.org/all/20261114040101.1043546-6-kuniyu@google.com/" target="_blank" rel="noreferrer">[PATCH v1 net-next 5/8] tcp: Skip collapsing if collapsed skb is less-dense.</a> <a class="header-anchor" href="#_895c85f2151c-·-patch-v1-net-next-5-8-tcp-skip-collapsing-if-collapsed-skb-is-less-dense" aria-label="Permalink to &quot;`895c85f2151c` · [[PATCH v1 net-next 5/8] tcp: Skip collapsing if collapsed skb is less-dense.](https://lore.kernel.org/all/20261114040101.1043546-6-kuniyu@google.com/)&quot;">​</a></h3><p><em>Kuniyuki Iwashima (<a href="mailto:kuniyu@google.com" target="_blank" rel="noreferrer">kuniyu@google.com</a>)｜netdev</em></p><p>tcp_collapse() 找到可合并 skb 后会连续合并 bloated skb，但某些情况下结果反而更大：一是 skb 已是最小尺寸（来自 skbuff_small_head 缓存，truesize 不变）；二是 SKB_HEAD_ALIGN() 与 alloc_skb() 中 kmalloc_size_roundup() 的取整效应可能使合并后的 truesize 超过原总和。补丁在合并结果密度更低时跳过合并。</p><blockquote><p><strong>学习价值</strong>：通过 truesize 取整细节揭示了 skb 内存布局的真实成本模型，帮助理解内核内存分配的粒度效应。</p></blockquote><h3 id="d43aa729e753-·-patch-v1-net-next-4-8-net-move-skb-small-head-cache-size-to-skbuff-h" tabindex="-1"><code>d43aa729e753</code> · <a href="https://lore.kernel.org/all/20261114040101.1043546-5-kuniyu@google.com/" target="_blank" rel="noreferrer">[PATCH v1 net-next 4/8] net: Move SKB_SMALL_HEAD_CACHE_SIZE to skbuff.h.</a> <a class="header-anchor" href="#d43aa729e753-·-patch-v1-net-next-4-8-net-move-skb-small-head-cache-size-to-skbuff-h" aria-label="Permalink to &quot;`d43aa729e753` · [[PATCH v1 net-next 4/8] net: Move SKB_SMALL_HEAD_CACHE_SIZE to skbuff.h.](https://lore.kernel.org/all/20261114040101.1043546-5-kuniyu@google.com/)&quot;">​</a></h3><p><em>Kuniyuki Iwashima (<a href="mailto:kuniyu@google.com" target="_blank" rel="noreferrer">kuniyu@google.com</a>)｜netdev</em></p><p>为让后续补丁能在 tcp_collapse() 中预计算 skb truesize，将 SKB_SMALL_HEAD_CACHE_SIZE 及其依赖从 net/core/skbuff.c、include/net/gro.h、include/net/tcp.h 移动到 include/linux/skbuff.h。</p><blockquote><p><strong>学习价值</strong>：一个典型的头文件重构准备补丁，展示了大型系列中代码组织调整的常见做法。</p></blockquote><h3 id="_0a9d170bc878-·-patch-v1-net-next-3-8-tcp-stop-collapsing-if-not-bloated" tabindex="-1"><code>0a9d170bc878</code> · <a href="https://lore.kernel.org/all/20261114040101.1043546-4-kuniyu@google.com/" target="_blank" rel="noreferrer">[PATCH v1 net-next 3/8] tcp: Stop collapsing if not bloated.</a> <a class="header-anchor" href="#_0a9d170bc878-·-patch-v1-net-next-3-8-tcp-stop-collapsing-if-not-bloated" aria-label="Permalink to &quot;`0a9d170bc878` · [[PATCH v1 net-next 3/8] tcp: Stop collapsing if not bloated.](https://lore.kernel.org/all/20261114040101.1043546-4-kuniyu@google.com/)&quot;">​</a></h3><p><em>Kuniyuki Iwashima (<a href="mailto:kuniyu@google.com" target="_blank" rel="noreferrer">kuniyu@google.com</a>)｜netdev</em></p><p>即使 skb 本身并不 bloated，tcp_collapse() 也会在下一个 skb 有重叠数据时开始合并，且一直持续到队列尾部或不可合并的 skb。这会导致低密度 skb 后面的高密度 4K-MSS GRO skb（scaling_ratio 98%）被重打包成更低密度的 skb，反而消耗更多内存。补丁在 skb 不 bloated 时停止合并。</p><blockquote><p><strong>学习价值</strong>：以具体数值例子分析 scaling_ratio 与合并决策的交互，是理解 TCP 接收缓冲区整理策略的绝佳材料。</p></blockquote><h3 id="_3fe85ed98e2e-·-patch-v1-net-next-2-8-tcp-don-t-collapse-high-density-skb" tabindex="-1"><code>3fe85ed98e2e</code> · <a href="https://lore.kernel.org/all/20261114040101.1043546-3-kuniyu@google.com/" target="_blank" rel="noreferrer">[PATCH v1 net-next 2/8] tcp: Don&#39;t collapse high density skb.</a> <a class="header-anchor" href="#_3fe85ed98e2e-·-patch-v1-net-next-2-8-tcp-don-t-collapse-high-density-skb" aria-label="Permalink to &quot;`3fe85ed98e2e` · [[PATCH v1 net-next 2/8] tcp: Don&#39;t collapse high density skb.](https://lore.kernel.org/all/20261114040101.1043546-3-kuniyu@google.com/)&quot;">​</a></h3><p><em>Kuniyuki Iwashima (<a href="mailto:kuniyu@google.com" target="_blank" rel="noreferrer">kuniyu@google.com</a>)｜netdev</em></p><p>tcp_collapse() 在 skb 密度低于 tp-&gt;scaling_ratio 或已读部分数据时开始合并，但新 skb 的最大 scaling_ratio 仅约 222（86%），若 4K-MSS GRO skb 将 tp-&gt;scaling_ratio 提升到更高，新合并的 skb 又会被判定为 bloated 而被反复合并。补丁避免对高密度 skb 进行合并。</p><blockquote><p><strong>学习价值</strong>：揭示了 scaling_ratio 动态更新与合并阈值之间的反馈问题，展示了性能优化中“避免反复折腾”的设计思路。</p></blockquote><h3 id="b55c0b9ccc5a-·-patch-v1-net-next-1-8-tcp-clean-up-the-first-loop-in-tcp-collapse" tabindex="-1"><code>b55c0b9ccc5a</code> · <a href="https://lore.kernel.org/all/20261114040101.1043546-2-kuniyu@google.com/" target="_blank" rel="noreferrer">[PATCH v1 net-next 1/8] tcp: Clean up the first loop in tcp_collapse().</a> <a class="header-anchor" href="#b55c0b9ccc5a-·-patch-v1-net-next-1-8-tcp-clean-up-the-first-loop-in-tcp-collapse" aria-label="Permalink to &quot;`b55c0b9ccc5a` · [[PATCH v1 net-next 1/8] tcp: Clean up the first loop in tcp_collapse().](https://lore.kernel.org/all/20261114040101.1043546-2-kuniyu@google.com/)&quot;">​</a></h3><p><em>Kuniyuki Iwashima (<a href="mailto:kuniyu@google.com" target="_blank" rel="noreferrer">kuniyu@google.com</a>)｜netdev</em></p><p>tcp_collapse() 第一个循环用于检测开始合并的 skb，但对 SYN/FIN 和 skb_frags_readable() 的判断分散在循环内外，存在重复测试。补丁统一使用 goto skip_this，将 end_of_skbs 替换为反转的循环条件，并调整 skb_frags_readable() 到完全重叠检查之后，简化了循环结构。</p><blockquote><p><strong>学习价值</strong>：典型的重构准备补丁，展示了在改动核心逻辑前先清理控制流的工程实践。</p></blockquote><h3 id="aac6d390bfa8-·-patch-v1-net-next-0-8-tcp-prevent-tcp-collapse-from-bloating-queue-1" tabindex="-1"><code>aac6d390bfa8</code> · <a href="https://lore.kernel.org/all/20261114040101.1043546-1-kuniyu@google.com/" target="_blank" rel="noreferrer">[PATCH v1 net-next 0/8] tcp: Prevent tcp_collapse() from bloating queue.</a> <a class="header-anchor" href="#aac6d390bfa8-·-patch-v1-net-next-0-8-tcp-prevent-tcp-collapse-from-bloating-queue-1" aria-label="Permalink to &quot;`aac6d390bfa8` · [[PATCH v1 net-next 0/8] tcp: Prevent tcp_collapse() from bloating queue.](https://lore.kernel.org/all/20261114040101.1043546-1-kuniyu@google.com/)&quot;">​</a></h3><p><em>Kuniyuki Iwashima (<a href="mailto:kuniyu@google.com" target="_blank" rel="noreferrer">kuniyu@google.com</a>)｜netdev</em></p><p>本系列是 commit 031c403d13e5 的后续，修复 tcp_collapse() 在 4K MSS 和 tp-&gt;scaling_ratio 场景下反而导致内存膨胀的问题。tcp_collapse() 的核心算法自 Linux-2.6.12 以来几乎未变，将可合并的 skb 重新打包到最多 SKB_MAX_ORDER() 大小的 skb 中，但 SKB_MAX_ORDER() 的 scaling ratio（222）低于典型 4K MSS 流的 tp-&gt;scaling_ratio（252），导致重打包后内存占用不降反升。</p><blockquote><p><strong>学习价值</strong>：展示了 TCP 接收队列内存管理与现代大 MSS 特性之间的历史遗留冲突，是理解 skb 合并机制和 sk_forward_alloc 记账的好案例。</p></blockquote><h2 id="文件系统与存储" tabindex="-1">文件系统与存储 <a class="header-anchor" href="#文件系统与存储" aria-label="Permalink to &quot;文件系统与存储&quot;">​</a></h2><h3 id="_87fc1ae77272-·-bug-report-nvme-pci-nvme-lost-after-s3-resume-csts-reads-all-ones-for-a-few-100-ms" tabindex="-1"><code>87fc1ae77272</code> · <a href="https://lore.kernel.org/all/598ee2b4-32aa-4ad3-99c7-db7f9a7e7736@pc-heini.de/" target="_blank" rel="noreferrer">[bug report] nvme-pci: NVMe lost after S3 resume, CSTS reads all-ones for a few 100 ms</a> <a class="header-anchor" href="#_87fc1ae77272-·-bug-report-nvme-pci-nvme-lost-after-s3-resume-csts-reads-all-ones-for-a-few-100-ms" aria-label="Permalink to &quot;`87fc1ae77272` · [[bug report] nvme-pci: NVMe lost after S3 resume, CSTS reads all-ones for a few 100 ms](https://lore.kernel.org/all/598ee2b4-32aa-4ad3-99c7-db7f9a7e7736@pc-heini.de/)&quot;">​</a></h3><p><em>Moritz Hiller (<a href="mailto:m.hiller@pc-heini.de" target="_blank" rel="noreferrer">m.hiller@pc-heini.de</a>)｜lkml</em></p><p>bug 报告：某桌面系统（X570 + Ryzen）在 S3 唤醒后约 5-10% 的概率 NVMe 控制器无法恢复，nvme_pci_enable() 中单次 readl(CSTS) 在恢复约 200ms 后仍读到全 1，控制器实际只是需要更长时间。作者用简单等待循环验证可行，但希望讨论正确的修复位置。</p><blockquote><p><strong>学习价值</strong>：典型的 PCIe 设备 S3 恢复时序问题报告，展示了如何定位硬件就绪等待逻辑应放在驱动的哪个层次，对学习驱动电源管理路径很有启发。</p></blockquote><h3 id="c8f0368c0a77-·-patch-v3-1-1-docs-filesystems-update-vfs-locking-documentation" tabindex="-1"><code>c8f0368c0a77</code> · <a href="https://lore.kernel.org/all/20261115001334.23026-2-mohamedalibouhaouala@gmail.com/" target="_blank" rel="noreferrer">[PATCH v3 1/1] docs: filesystems: update VFS locking documentation</a> <a class="header-anchor" href="#c8f0368c0a77-·-patch-v3-1-1-docs-filesystems-update-vfs-locking-documentation" aria-label="Permalink to &quot;`c8f0368c0a77` · [[PATCH v3 1/1] docs: filesystems: update VFS locking documentation](https://lore.kernel.org/all/20261115001334.23026-2-mohamedalibouhaouala@gmail.com/)&quot;">​</a></h3><p><em>mohamedalibouhaouala (<a href="mailto:mohamedalibouhaouala@gmail.com" target="_blank" rel="noreferrer">mohamedalibouhaouala@gmail.com</a>)｜linux-mm</em></p><p>更新 Documentation/filesystems/locking.rst 中过时的 VFS 操作原型，使其与当前定义一致；补充缺失的 d_prune 和 sync_inode_metadata 回调，修正现有操作的函数签名，并在 locking 表中加入 sync_inode_metadata。已获 Jan Kara 的 Reviewed-by。</p><blockquote><p><strong>学习价值</strong>：VFS locking 文档是理解各文件系统回调所需锁约束的权威参考，此更新帮助学习者获取准确的接口签名。</p></blockquote><h3 id="_25eebe849fa3-·-patch-v3-0-1-docs-filesystems-update-vfs-locking-documentation" tabindex="-1"><code>25eebe849fa3</code> · <a href="https://lore.kernel.org/all/20261115001334.23026-1-mohamedalibouhaouala@gmail.com/" target="_blank" rel="noreferrer">[PATCH v3 0/1] docs: filesystems: update VFS locking documentation</a> <a class="header-anchor" href="#_25eebe849fa3-·-patch-v3-0-1-docs-filesystems-update-vfs-locking-documentation" aria-label="Permalink to &quot;`25eebe849fa3` · [[PATCH v3 0/1] docs: filesystems: update VFS locking documentation](https://lore.kernel.org/all/20261115001334.23026-1-mohamedalibouhaouala@gmail.com/)&quot;">​</a></h3><p><em>mohamedalibouhaouala (<a href="mailto:mohamedalibouhaouala@gmail.com" target="_blank" rel="noreferrer">mohamedalibouhaouala@gmail.com</a>)｜linux-mm</em></p><p>作者更正此前误发 v2 的问题，重新提交 v3 版本的 VFS locking 文档更新补丁：更新过时的操作原型、补充 d_prune 和 sync_inode_metadata 回调并修正 locking 表。v3 基于 latest upstream master 并包含 Jan Kara 的 Reviewed-by 标签。</p><blockquote><p><strong>学习价值</strong>：内容与 v2 相同，主要展示了补丁版本管理中的常见失误与更正流程，对学习邮件提交礼仪有参考意义。</p></blockquote><h3 id="_9ede6a767858-·-patch-v2-docs-filesystems-update-vfs-locking-documentation" tabindex="-1"><code>9ede6a767858</code> · <a href="https://lore.kernel.org/all/20261114235426.20408-1-mohamedalibouhaouala@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2] docs: filesystems: update VFS locking documentation</a> <a class="header-anchor" href="#_9ede6a767858-·-patch-v2-docs-filesystems-update-vfs-locking-documentation" aria-label="Permalink to &quot;`9ede6a767858` · [[PATCH v2] docs: filesystems: update VFS locking documentation](https://lore.kernel.org/all/20261114235426.20408-1-mohamedalibouhaouala@gmail.com/)&quot;">​</a></h3><p><em>mohamedalibouhaouala (<a href="mailto:mohamedalibouhaouala@gmail.com" target="_blank" rel="noreferrer">mohamedalibouhaouala@gmail.com</a>)｜linux-mm</em></p><p>v2 版本更新 Documentation/filesystems/locking.rst：修正过时的 VFS 操作原型与签名，补充缺失的 d_prune 和 sync_inode_metadata 回调，并在 locking 表中加入 sync_inode_metadata。v2 变更是使用贡献者全名作为 author 和 sign-off。</p><blockquote><p><strong>学习价值</strong>：文档补丁的典型演进过程，可学习内核社区对 sign-off 命名规范的要求以及文档维护流程。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="b649d1e8af7d-·-patch-2-2-gpu-nova-core-remove-unnecessary-firmware-pin-init" tabindex="-1"><code>b649d1e8af7d</code> · <a href="https://lore.kernel.org/all/20261114234324.82387-2-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH 2/2] gpu: nova-core: remove unnecessary firmware pin-init</a> <a class="header-anchor" href="#b649d1e8af7d-·-patch-2-2-gpu-nova-core-remove-unnecessary-firmware-pin-init" aria-label="Permalink to &quot;`b649d1e8af7d` · [[PATCH 2/2] gpu: nova-core: remove unnecessary firmware pin-init](https://lore.kernel.org/all/20261114234324.82387-2-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux</em></p><p>在 SGTable 不再需要 pinning 之后，从 nova-core 驱动的 Radix3 和 GspFirmware 中移除多余的 pin-init 机制，净减少约 15 行代码。这是 Rust 抽象层 API 演进带动下游驱动简化的典型例子。</p><blockquote><p><strong>学习价值</strong>：说明抽象层 API 的安全性改进（如取消 pin-init 要求）如何传导到具体驱动代码的简化，对学习 Rust 内核驱动的维护演进有参考价值。</p></blockquote><h3 id="_0ab5c063be52-·-patch-1-2-rust-scatterlist-tie-owned-tables-to-the-device-s-bound-lifetime" tabindex="-1"><code>0ab5c063be52</code> · <a href="https://lore.kernel.org/all/20261114234324.82387-1-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH 1/2] rust: scatterlist: tie owned tables to the device&#39;s bound lifetime</a> <a class="header-anchor" href="#_0ab5c063be52-·-patch-1-2-rust-scatterlist-tie-owned-tables-to-the-device-s-bound-lifetime" aria-label="Permalink to &quot;`0ab5c063be52` · [[PATCH 1/2] rust: scatterlist: tie owned tables to the device&#39;s bound lifetime](https://lore.kernel.org/all/20261114234324.82387-1-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux</em></p><p>为 scatterlist 的 Owned 类型添加生命周期参数，将拥有的 scatter-gather 表绑定到 device 的 bound 作用域，确保 DMA 映射在设备解绑前释放。通过让 DmaMappedSgt 拥有 RawSGTable 并借用 Device&lt;Bound&gt;，其析构函数先解除映射再释放表，消除了内部自引用指针，使映射构造函数无需 unsafe 的自引用即可安全实现。</p><blockquote><p><strong>学习价值</strong>：演示了如何用 Rust 生命周期系统在类型层面编码资源释放顺序约束，是学习内核 Rust 安全抽象设计（尤其是 DMA 映射生命周期）的优秀范例。</p></blockquote><h3 id="d3f1c5091f37-·-patch-2-2-rust-gpu-buddy-store-the-allocator-inside-the-mutex" tabindex="-1"><code>d3f1c5091f37</code> · <a href="https://lore.kernel.org/all/20261114200703.33229-3-mbkchelofficialdev@gmail.com/" target="_blank" rel="noreferrer">[PATCH 2/2] rust: gpu: buddy: store the allocator inside the Mutex</a> <a class="header-anchor" href="#d3f1c5091f37-·-patch-2-2-rust-gpu-buddy-store-the-allocator-inside-the-mutex" aria-label="Permalink to &quot;`d3f1c5091f37` · [[PATCH 2/2] rust: gpu: buddy: store the allocator inside the Mutex](https://lore.kernel.org/all/20261114200703.33229-3-mbkchelofficialdev@gmail.com/)&quot;">​</a></h3><p><em>Ivan Tverdokhleb (<a href="mailto:mbkchelofficialdev@gmail.com" target="_blank" rel="noreferrer">mbkchelofficialdev@gmail.com</a>)｜rust-for-linux</em></p><p>将 GPU buddy 分配器的 C 结构 gpu_buddy 直接放入 Mutex&lt;Opaque&lt;gpu_buddy&gt;&gt; 中，替代原先 Mutex&lt;()&gt; 加独立数据的组合。这样分配器只能通过 lock guard 访问，由编译器强制保证访问时持有锁，同时移除了 GpuBuddyGuard 中不再需要的 inner 字段。</p><blockquote><p><strong>学习价值</strong>：展示了如何用类型系统将锁与被保护数据的绑定关系静态化，是理解 Rust 内核中锁保护数据建模的经典实践。</p></blockquote><h3 id="_2a3ef0d86f3a-·-patch-1-2-rust-sync-lock-allow-fallible-initializers-in-lock-new" tabindex="-1"><code>2a3ef0d86f3a</code> · <a href="https://lore.kernel.org/all/20261114200703.33229-2-mbkchelofficialdev@gmail.com/" target="_blank" rel="noreferrer">[PATCH 1/2] rust: sync: lock: allow fallible initializers in Lock::new</a> <a class="header-anchor" href="#_2a3ef0d86f3a-·-patch-1-2-rust-sync-lock-allow-fallible-initializers-in-lock-new" aria-label="Permalink to &quot;`2a3ef0d86f3a` · [[PATCH 1/2] rust: sync: lock: allow fallible initializers in Lock::new](https://lore.kernel.org/all/20261114200703.33229-2-mbkchelofficialdev@gmail.com/)&quot;">​</a></h3><p><em>Ivan Tverdokhleb (<a href="mailto:mbkchelofficialdev@gmail.com" target="_blank" rel="noreferrer">mbkchelofficialdev@gmail.com</a>)｜rust-for-linux</em></p><p>修改 Lock::new() 使其接受可失败的初始化器：将错误类型 E 泛型化，接受任何 impl PinInit&lt;T, E&gt; 并返回 impl PinInit&lt;Self, E&gt;，其中 E 需实现 From&lt;Infallible&gt;。此前 impl PinInit&lt;T&gt; 默认错误类型为 Infallible，导致 Opaque::try_ffi_init() 这类可失败初始化器无法被 Mutex 或 SpinLock 包装。</p><blockquote><p><strong>学习价值</strong>：深入讲解了 Rust 内核中 pin-init 机制的错误类型设计，对理解内核 Rust 初始化基础设施的泛型设计很有帮助。</p></blockquote><h3 id="_40e2c3ba6844-·-patch-0-2-rust-sync-lock-allow-fallible-initializers-in-lock-new" tabindex="-1"><code>40e2c3ba6844</code> · <a href="https://lore.kernel.org/all/20261114200703.33229-1-mbkchelofficialdev@gmail.com/" target="_blank" rel="noreferrer">[PATCH 0/2] rust: sync: lock: allow fallible initializers in Lock::new</a> <a class="header-anchor" href="#_40e2c3ba6844-·-patch-0-2-rust-sync-lock-allow-fallible-initializers-in-lock-new" aria-label="Permalink to &quot;`40e2c3ba6844` · [[PATCH 0/2] rust: sync: lock: allow fallible initializers in Lock::new](https://lore.kernel.org/all/20261114200703.33229-1-mbkchelofficialdev@gmail.com/)&quot;">​</a></h3><p><em>Ivan Tverdokhleb (<a href="mailto:mbkchelofficialdev@gmail.com" target="_blank" rel="noreferrer">mbkchelofficialdev@gmail.com</a>)｜rust-for-linux</em></p><p>本系列两补丁：第一补丁使 Lock::new() 对被保护数据的初始化器错误类型泛型化，从而可包装 Opaque::try_ffi_init() 等可失败初始化器；第二补丁借此将 GPU buddy 分配器的 gpu_buddy 结构直接放入 Mutex，使分配器只能通过 lock guard 访问，解决遗留 TODO。</p><blockquote><p><strong>学习价值</strong>：一个完整的&#39;基础设施改进 + 下游应用&#39;的系列补丁，展示了内核 Rust 抽象如何逐步消除 TODO 并增强类型安全。</p></blockquote><h3 id="adfa57deb741-·-patch-v2-rust-kernel-fix-lifetime-of-copy-from-iter-raw" tabindex="-1"><code>adfa57deb741</code> · <a href="https://lore.kernel.org/all/20261114132156.49243-1-marawanzein222@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2] rust: kernel: fix lifetime of copy_from_iter_raw</a> <a class="header-anchor" href="#adfa57deb741-·-patch-v2-rust-kernel-fix-lifetime-of-copy-from-iter-raw" aria-label="Permalink to &quot;`adfa57deb741` · [[PATCH v2] rust: kernel: fix lifetime of copy_from_iter_raw](https://lore.kernel.org/all/20261114132156.49243-1-marawanzein222@gmail.com/)&quot;">​</a></h3><p><em>Marwan Mohamed Zein (<a href="mailto:marawanzein222@gmail.com" target="_blank" rel="noreferrer">marawanzein222@gmail.com</a>)｜rust-for-linux</em></p><p>修复 copy_from_iter_raw 的生命周期问题：返回的 slice 实际派生自参数 out，但方法的生命周期省略规则将其绑定到 self，可能允许返回的 slice 超出其底层缓冲区的存活期。补丁显式将返回生命周期绑定到 out，并附带 Fixes 和 stable 回溯标签。</p><blockquote><p><strong>学习价值</strong>：一个简洁但典型的 Rust 生命周期省略规则陷阱案例，提醒学习者在方法返回引用时仔细核对真实的生命周期来源。</p></blockquote><h3 id="d4b7b026c788-·-patch-net-next-v2-3-3-rust-net-phy-pass-a-maybelocked-device-to-soft-reset" tabindex="-1"><code>d4b7b026c788</code> · <a href="https://lore.kernel.org/all/20261114-exp-phy-rs-maybelocked-v2-3-19a4dd658b6b@gmail.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 3/3] rust: net: phy: pass a MaybeLocked device to soft_reset</a> <a class="header-anchor" href="#d4b7b026c788-·-patch-net-next-v2-3-3-rust-net-phy-pass-a-maybelocked-device-to-soft-reset" aria-label="Permalink to &quot;`d4b7b026c788` · [[PATCH net-next v2 3/3] rust: net: phy: pass a MaybeLocked device to soft_reset](https://lore.kernel.org/all/20261114-exp-phy-rs-maybelocked-v2-3-19a4dd658b6b@gmail.com/)&quot;">​</a></h3><p><em>SeungJong Ha (<a href="mailto:engineer.jjhama@gmail.com" target="_blank" rel="noreferrer">engineer.jjhama@gmail.com</a>)｜rust-for-linux</em></p><p>phy_init_hw() 调用 soft_reset 回调时有时持有 phy_device-&gt;lock 有时不持有，但 soft_reset_callback 却向驱动传递 Locked 设备并声称锁已持有。本补丁改为传递 &amp;mut Device&lt;MaybeLocked&gt; 并修正 SAFETY 注释，同时更新唯一实现 ax88796b_rust。</p><blockquote><p><strong>学习价值</strong>：展示了如何通过类型系统如实反映 C 侧回调的锁状态，是学习跨语言抽象中锁语义正确建模的好例子。</p></blockquote><h3 id="_671c5c1005b4-·-patch-net-next-v2-2-3-rust-net-phy-make-device-generic-over-a-lock-context" tabindex="-1"><code>671c5c1005b4</code> · <a href="https://lore.kernel.org/all/20261114-exp-phy-rs-maybelocked-v2-2-19a4dd658b6b@gmail.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 2/3] rust: net: phy: make Device generic over a lock context</a> <a class="header-anchor" href="#_671c5c1005b4-·-patch-net-next-v2-2-3-rust-net-phy-make-device-generic-over-a-lock-context" aria-label="Permalink to &quot;`671c5c1005b4` · [[PATCH net-next v2 2/3] rust: net: phy: make Device generic over a lock context](https://lore.kernel.org/all/20261114-exp-phy-rs-maybelocked-v2-2-19a4dd658b6b@gmail.com/)&quot;">​</a></h3><p><em>SeungJong Ha (<a href="mailto:engineer.jjhama@gmail.com" target="_blank" rel="noreferrer">engineer.jjhama@gmail.com</a>)｜rust-for-linux</em></p><p>将 PHY 抽象中的 Device 泛型化为锁上下文 Locked（默认）或 MaybeLocked，仿照 device::Device 对设备上下文的处理方式，并将不需要锁的方法移到两种上下文中均可调用。本补丁为后续传递 MaybeLocked 设备做准备，无功能变化。</p><blockquote><p><strong>学习价值</strong>：演示了用类型状态（typestate）模式在 Rust 抽象中区分锁持有状态的设计方法，对学习内核 API 的类型安全建模很有价值。</p></blockquote><h3 id="b6ff437e12e7-·-patch-net-next-v2-1-3-rust-net-phy-drop-read-mmd-and-write-mmd-from-driver" tabindex="-1"><code>b6ff437e12e7</code> · <a href="https://lore.kernel.org/all/20261114-exp-phy-rs-maybelocked-v2-1-19a4dd658b6b@gmail.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 1/3] rust: net: phy: drop read_mmd and write_mmd from Driver</a> <a class="header-anchor" href="#b6ff437e12e7-·-patch-net-next-v2-1-3-rust-net-phy-drop-read-mmd-and-write-mmd-from-driver" aria-label="Permalink to &quot;`b6ff437e12e7` · [[PATCH net-next v2 1/3] rust: net: phy: drop read_mmd and write_mmd from Driver](https://lore.kernel.org/all/20261114-exp-phy-rs-maybelocked-v2-1-19a4dd658b6b@gmail.com/)&quot;">​</a></h3><p><em>SeungJong Ha (<a href="mailto:engineer.jjhama@gmail.com" target="_blank" rel="noreferrer">engineer.jjhama@gmail.com</a>)｜rust-for-linux</em></p><p>移除 Rust PHY Driver 抽象中的 read_mmd 和 write_mmd 回调：__phy_read_mmd() 和 __phy_write_mmd() 调用它们时只持有 MDIO 总线锁而不一定持有 phy_device-&gt;lock（如 hwmon 读取路径），而 Device 上的寄存器访问器会再次获取总线锁导致死锁风险。由于没有 Rust 驱动实现这些回调，先移除待有用户和表达 MDIO 总线锁上下文的方式后再重新设计。</p><blockquote><p><strong>学习价值</strong>：体现了&#39;没有用户且有锁语义缺陷的抽象宁可删除&#39;的内核维护原则，同时揭示了 PHYLIB 中 phy_device-&gt;lock 与 MDIO 总线锁的复杂交互。</p></blockquote><h3 id="_26569841c7e7-·-patch-net-next-v2-0-3-rust-net-phy-soft-reset-may-run-without-phy-device-lock-1" tabindex="-1"><code>26569841c7e7</code> · <a href="https://lore.kernel.org/all/20261114-exp-phy-rs-maybelocked-v2-0-19a4dd658b6b@gmail.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 0/3] rust: net: phy: soft_reset may run without phy_device-&gt;lock</a> <a class="header-anchor" href="#_26569841c7e7-·-patch-net-next-v2-0-3-rust-net-phy-soft-reset-may-run-without-phy-device-lock-1" aria-label="Permalink to &quot;`26569841c7e7` · [[PATCH net-next v2 0/3] rust: net: phy: soft_reset may run without phy_device-&gt;lock](https://lore.kernel.org/all/20261114-exp-phy-rs-maybelocked-v2-0-19a4dd658b6b@gmail.com/)&quot;">​</a></h3><p><em>SeungJong Ha (<a href="mailto:engineer.jjhama@gmail.com" target="_blank" rel="noreferrer">engineer.jjhama@gmail.com</a>)｜rust-for-linux</em></p><p>该补丁系列修复 Rust PHY 抽象中 <code>soft_reset</code> 的锁假设错误：原注释声称 PHYLIB 持有 <code>phy_device-&gt;lock</code>，但 <code>phy_init_hw()</code> 实际上在有锁和无锁两种情况下都会调用它。作者通过审计 Rust 抽象的 SAFETY 注释与 C 调用方的一致性，并用 Clang 的 context analysis 确认了该问题。补丁 1 删除了同样有错误锁声明且无用户的 <code>read_mmd</code>/<code>write_mmd</code>，补丁 2-3 引入 <code>MaybeLocked</code> 锁上下文类型使 <code>Device</code> 泛型化，让类型系统精确表达锁状态。</p><blockquote><p><strong>学习价值</strong>：这是学习 Rust 抽象层如何用类型系统（如 <code>MaybeLocked</code>）表达 C 代码中隐式锁约定的绝佳案例，也展示了 SAFETY 注释审计的方法论。</p></blockquote><h3 id="dae5de77263f-·-patch-rust-kernel-fix-lifetime-of-copy-from-iter-raw" tabindex="-1"><code>dae5de77263f</code> · <a href="https://lore.kernel.org/all/20261114024515.1000882-1-marawanzein222@gmail.com/" target="_blank" rel="noreferrer">[PATCH] rust: kernel: fix lifetime of copy_from_iter_raw</a> <a class="header-anchor" href="#dae5de77263f-·-patch-rust-kernel-fix-lifetime-of-copy-from-iter-raw" aria-label="Permalink to &quot;`dae5de77263f` · [[PATCH] rust: kernel: fix lifetime of copy_from_iter_raw](https://lore.kernel.org/all/20261114024515.1000882-1-marawanzein222@gmail.com/)&quot;">​</a></h3><p><em>Marwan Mohamed Zein (<a href="mailto:marawanzein222@gmail.com" target="_blank" rel="noreferrer">marawanzein222@gmail.com</a>)｜rust-for-linux</em></p><p>该补丁修复 <code>rust/kernel/iov.rs</code> 中 <code>copy_from_iter_raw</code> 的生命周期问题：返回的 slice 实际派生自 <code>out</code> 缓冲区，但由于方法的生命周期省略规则，其生命周期被错误地绑定到 <code>self</code>。修复方式是显式将返回生命周期绑定到 <code>out</code>，确保返回的 slice 不会比其底层缓冲区存活更久。</p><blockquote><p><strong>学习价值</strong>：一个展示 Rust 生命周期省略规则在方法签名中可能产生误导性绑定的精简案例，对理解内核 Rust 抽象中的内存安全设计很有帮助。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="_289c181ae347-·-redox-os-gets-golang-working-gimp-ported-simplified-ai-policy" tabindex="-1"><code>289c181ae347</code> · <a href="https://www.phoronix.com/news/Redox-OS-Golang-GIMP" target="_blank" rel="noreferrer">Redox OS Gets Golang Working, GIMP Ported &amp; Simplified AI Policy</a> <a class="header-anchor" href="#_289c181ae347-·-redox-os-gets-golang-working-gimp-ported-simplified-ai-policy" aria-label="Permalink to &quot;`289c181ae347` · [Redox OS Gets Golang Working, GIMP Ported &amp; Simplified AI Policy](https://www.phoronix.com/news/Redox-OS-Golang-GIMP)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>基于 Rust 从零编写的开源操作系统 Redox OS 发布十月开发总结，Golang 已可在其上运行，GIMP 完成移植，NUMA 支持取得进展，并简化了 AI 政策。该系统展示了 Rust 在完整 OS 内核层面的实践。</p><blockquote><p><strong>学习价值</strong>：对关注 Rust in Linux 及操作系统从零构建的学习者有参考价值，可对比 Linux 内核与 Redox 的设计取舍。</p></blockquote><h3 id="e57a3ccdba5d-·-basic-support-for-the-apple-m5-expected-to-land-for-linux-7-5" tabindex="-1"><code>e57a3ccdba5d</code> · <a href="https://www.phoronix.com/news/Apple-M5-For-Linux-7.5" target="_blank" rel="noreferrer">Basic Support For The Apple M5 Expected To Land For Linux 7.5</a> <a class="header-anchor" href="#e57a3ccdba5d-·-basic-support-for-the-apple-m5-expected-to-land-for-linux-7-5" aria-label="Permalink to &quot;`e57a3ccdba5d` · [Basic Support For The Apple M5 Expected To Land For Linux 7.5](https://www.phoronix.com/news/Apple-M5-For-Linux-7.5)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Apple M5 SoC 基础款的基础支持补丁已进入 &quot;apple-soc/dt-7.5&quot; Git 分支，预计随 Linux 7.5 内核合并。这主要涉及 device tree 层面的最早期 enablement，尚不包含完整功能支持。</p><blockquote><p><strong>学习价值</strong>：展示了新 SoC 支持进入主线内核的典型流程（先 DT 基础描述，再逐步补全驱动），对理解内核平台 enablement 节奏有帮助。</p></blockquote><h3 id="c3c639cd35c4-·-intel-begins-linux-kernel-enablement-for-coral-rapids-razor-lake" tabindex="-1"><code>c3c639cd35c4</code> · <a href="https://www.phoronix.com/news/Linux-Coral-Rapids-Razor-Lake" target="_blank" rel="noreferrer">Intel Begins Linux Kernel Enablement For Coral Rapids &amp; Razor Lake</a> <a class="header-anchor" href="#c3c639cd35c4-·-intel-begins-linux-kernel-enablement-for-coral-rapids-razor-lake" aria-label="Permalink to &quot;`c3c639cd35c4` · [Intel Begins Linux Kernel Enablement For Coral Rapids &amp; Razor Lake](https://www.phoronix.com/news/Linux-Coral-Rapids-Razor-Lake)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Intel 开始为未来的服务器处理器 Coral Rapids 和桌面/移动处理器 Razor Lake 提交首批 Linux 内核补丁，与 GCC 编译器初始补丁同步推进。目前处于非常早期的 enablement 阶段。</p><blockquote><p><strong>学习价值</strong>：可观察 Intel 新平台在内核中提前数年启动 enablement 的节奏，了解 CPU 厂商与内核社区的协作模式。</p></blockquote><h3 id="_9d63e25f0af0-·-rugged-emdoor-laptops-beginning-to-see-improved-linux-support" tabindex="-1"><code>9d63e25f0af0</code> · <a href="https://www.phoronix.com/news/Emdoor-Linux-Platform-Driver" target="_blank" rel="noreferrer">Rugged Emdoor Laptops Beginning To See Improved Linux Support</a> <a class="header-anchor" href="#_9d63e25f0af0-·-rugged-emdoor-laptops-beginning-to-see-improved-linux-support" aria-label="Permalink to &quot;`9d63e25f0af0` · [Rugged Emdoor Laptops Beginning To See Improved Linux Support](https://www.phoronix.com/news/Emdoor-Linux-Platform-Driver)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>三防笔记本和平板厂商 Emdoor 的设备正在通过一个新的 platform driver 获得改进的 Linux 支持。这类驱动通常处理设备的按键、传感器、EC 等平台特定功能。</p><blockquote><p><strong>学习价值</strong>：展示了嵌入式/行业设备如何通过 platform driver 进入主线内核，是学习 x86 平台驱动开发的实例。</p></blockquote><h3 id="d721244169be-·-kde-plasma-6-9-finally-allows-xwayland-to-run-on-demand-new-wobbly-windows-presets" tabindex="-1"><code>d721244169be</code> · <a href="https://www.phoronix.com/news/Plasma-6.9-XWayland-On-Demand" target="_blank" rel="noreferrer">KDE Plasma 6.9 Finally Allows XWayland To Run On-Demand, New Wobbly Windows Presets</a> <a class="header-anchor" href="#d721244169be-·-kde-plasma-6-9-finally-allows-xwayland-to-run-on-demand-new-wobbly-windows-presets" aria-label="Permalink to &quot;`d721244169be` · [KDE Plasma 6.9 Finally Allows XWayland To Run On-Demand, New Wobbly Windows Presets](https://www.phoronix.com/news/Plasma-6.9-XWayland-On-Demand)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>KDE Plasma 6.9 终于支持 XWayland 按需启动，并新增 Wobbly Windows 预设。这是桌面环境层面的进展，与 Linux 内核本身无直接关系。</p><blockquote><p><strong>学习价值</strong>：对内核学习价值有限，仅可作为了解用户空间图形栈（XWayland/Wayland）生态的背景信息。</p></blockquote><h3 id="_7acd3e73a5ab-·-freebsd-15-2-beta-2-delivers-updated-openssl-bug-fixes" tabindex="-1"><code>7acd3e73a5ab</code> · <a href="https://www.phoronix.com/news/FreeBSD-15.2-Beta-2" target="_blank" rel="noreferrer">FreeBSD 15.2 Beta 2 Delivers Updated OpenSSL, Bug Fixes</a> <a class="header-anchor" href="#_7acd3e73a5ab-·-freebsd-15-2-beta-2-delivers-updated-openssl-bug-fixes" aria-label="Permalink to &quot;`7acd3e73a5ab` · [FreeBSD 15.2 Beta 2 Delivers Updated OpenSSL, Bug Fixes](https://www.phoronix.com/news/FreeBSD-15.2-Beta-2)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>FreeBSD 15.2 Beta 2 发布，更新了 OpenSSL 并修复若干 bug。该版本带来更好的笔记本/桌面硬件支持、实验性的在 Linux/macOS 上交叉构建基础包、更新的 LLVM/Clang 和 OpenZFS 支持。</p><blockquote><p><strong>学习价值</strong>：可作为对比 FreeBSD 与 Linux 内核演进方向的参考，尤其是 OpenZFS 与交叉构建等基础设施话题。</p></blockquote><h3 id="baf87c49ac1c-·-rfc-patch-v4-1-4-mm-zsmalloc-support-objects-compressed-based-on-multiple-pages" tabindex="-1"><code>baf87c49ac1c</code> · <a href="https://lore.kernel.org/all/20261115024455.1465726-2-zhaonanzhe@xiaomi.com/" target="_blank" rel="noreferrer">[RFC PATCH v4 1/4] mm: zsmalloc: support objects compressed based on multiple pages</a> <a class="header-anchor" href="#baf87c49ac1c-·-rfc-patch-v4-1-4-mm-zsmalloc-support-objects-compressed-based-on-multiple-pages" aria-label="Permalink to &quot;`baf87c49ac1c` · [[RFC PATCH v4 1/4] mm: zsmalloc: support objects compressed based on multiple pages](https://lore.kernel.org/all/20261115024455.1465726-2-zhaonanzhe@xiaomi.com/)&quot;">​</a></h3><p><em>Nanzhe Zhao (<a href="mailto:zhaonanzhe@xiaomi.com" target="_blank" rel="noreferrer">zhaonanzhe@xiaomi.com</a>)｜lkml</em></p><p>该补丁为 zsmalloc 引入基于多页的压缩对象存储支持，定义 ZSMALLOC_MULTI_PAGES_ORDER 配置项（默认 2，与匿名 mTHP 的最小 order 匹配）。此前大 folio 按 PAGE_SIZE 逐页压缩，改为更大粒度后可同时节省内存和 CPU 资源。</p><blockquote><p><strong>学习价值</strong>：是本系列补丁的基础设施部分，适合学习 zsmalloc 分配器内部结构以及其与 mTHP 粒度对齐的设计思路。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>a66a51f5715e</code> · <a href="https://lore.kernel.org/all/20261115024455.1465726-1-zhaonanzhe@xiaomi.com/" target="_blank" rel="noreferrer">[RFC PATCH v4 0/4] mTHP-friendly compression in zsmalloc and zram based on multi-pages</a></li><li><code>aac6d390bfa8</code> · <a href="https://lore.kernel.org/all/20261114040101.1043546-1-kuniyu@google.com/" target="_blank" rel="noreferrer">[PATCH v1 net-next 0/8] tcp: Prevent tcp_collapse() from bloating queue.</a></li><li><code>bad9ce49788a</code> · <a href="https://lore.kernel.org/all/20261113-b4-disp-1a9ab9b0-v1-0-4a7c8d85d849@proton.me/" target="_blank" rel="noreferrer">[PATCH net 0/4] net/smc: fix the failover cursor switch and wrap rollover</a></li><li><code>26569841c7e7</code> · <a href="https://lore.kernel.org/all/20261114-exp-phy-rs-maybelocked-v2-0-19a4dd658b6b@gmail.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 0/3] rust: net: phy: soft_reset may run without phy_device-&gt;lock</a></li><li><code>1d6e3581e68e</code> · <a href="https://lore.kernel.org/all/20261114040943.219870-1-demyansh@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 0/2] arm64: csum: Add fused copy and Internet checksum</a></li></ul>',242)])])}const u=a(l,[["render",n]]);export{h as __pageData,u as default};
